"""Vista móvil única. Los comandos mantienen las confirmaciones del servidor."""
from victor.integrations.keyboard_client import KEYBOARD_JS

PAGE = r'''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>VICTOR · Escritorio local</title><style>
*{box-sizing:border-box}body{background:#0d111c;color:#edf2ff;font:15px system-ui;margin:16px}h1{font-weight:800;font-size:25px}button,input,textarea{font:inherit;padding:12px;border-radius:14px;border:1px solid #29344a;background:#222b3b;color:inherit}button{touch-action:manipulation}input,textarea{width:100%;margin:6px 0}small{color:#9ba9c3}#screenBox{height:60vh;min-height:200px;display:flex;align-items:center;justify-content:center;border-radius:24px;background:#171e2e;overflow:hidden;margin:12px 0}#view{display:block;width:100%;height:100%;object-fit:contain;touch-action:none}#keyboardBox[hidden]{display:none}.controls{display:flex;flex-wrap:wrap;gap:8px}#status{min-height:40px}#modifiers input,textarea{width:auto}</style>
<h1>VICTOR · Tu escritorio</h1><small>● Red local · acciones supervisadas desde el PC</small>
<p id="status">Conectando…</p><input id="window" placeholder="Título exacto de la ventana que quieres controlar" aria-label="Ventana destino">
<div id="screenBox"><img id="view" alt="Autoriza compartir pantalla en el PC para ver el escritorio"></div>
<div class="controls"><button id="keyboard">⌨ Teclado</button><button id="screen">🖥 Renovar pantalla · 60 s</button><button id="stop">Detener</button></div>
<p id="keyboardStatus">Teclado conectando…</p><section id="keyboardBox" hidden><textarea id="typing" rows="2" autocomplete="off" autocapitalize="off" spellcheck="false" aria-label="Teclado remoto" placeholder="Escribe: se enviará directamente a la ventana del PC"></textarea>
<div id="modifiers"><label><input type="checkbox" id="ctrl">Ctrl</label><label><input type="checkbox" id="alt">Alt</label><label><input type="checkbox" id="shift">Shift</label></div>
<div class="controls"><button data-key="enter">Intro</button><button data-key="esc">Escape</button><button data-key="backspace">Retroceso</button><button data-key="tab">Tab</button><button data-key="left">←</button><button data-key="right">→</button><button data-key="up">↑</button><button data-key="down">↓</button><button data-key="a">A</button><button data-key="c">C</button><button data-key="v">V</button><button data-key="delete">Supr</button><button data-key="f4">F4</button></div></section>
<p>Un dedo: mover y hacer clic. Dos dedos: scroll. El ratón mantiene su confirmación en el PC. El QR autoriza el texto normal. Atajos peligrosos requieren EJECUTAR. Ctrl/Alt/Shift se aplican mientras estén marcados; se liberan en el PC tras cada atajo.</p>
<script>
'use strict';
const status=document.getElementById('status'),target=document.getElementById('window'),view=document.getElementById('view'),typing=document.getElementById('typing');
let ws,video,keyboardChannel,focusInfo=null,lastControl=Date.now(),session='',pending=false,frame=null,imageURL='',imageTime=0,metadata=null,lastScroll=0,composition=false,typingTimer,buffer='',queue=[],running=true;
const points=new Map();let gesture=null;
const code=location.hash.slice(1);history.replaceState(null,'',location.pathname);
function connect(path,auth){return new Promise((resolve,reject)=>{const s=new WebSocket('wss://'+location.host+path);const timeout=setTimeout(()=>{s.close();reject(Error('HTTPS no responde. Revisa Wi-Fi y certificado; si caducó, reinicia el servidor del PC y escanea un QR nuevo.'));},8000);s.onopen=()=>s.send(JSON.stringify(auth));s.onerror=()=>{clearTimeout(timeout);s.close();reject(Error('No se pudo conectar. Revisa Wi-Fi/HTTPS. Si el certificado caducó, reinicia el remoto del PC y acepta el certificado de su IP al escanear un nuevo QR.'));};s.onclose=()=>{clearTimeout(timeout);reject(Error('Conexión cerrada. Genera un QR nuevo.'));};s.onmessage=e=>{clearTimeout(timeout);try{const msg=JSON.parse(e.data);if(msg.error){s.close();reject(Error(msg.error))}else resolve([s,msg]);}catch(_){s.close();reject(Error('Respuesta de conexión inválida.'));}};});}
function send(tool,args){if(!running||!ws||ws.readyState!==1)return false;if(pending){status.textContent='Hay una acción esperando confirmación en el PC.';return false;}pending=true;ws.send(JSON.stringify({tool,args}));status.textContent='Confirma en el PC para ejecutar.';return true;}
function pump(){if(!pending&&queue.length){const item=queue.shift();if(!send(item.tool,item.args))queue.unshift(item)}}
function enqueue(tool,args){if(queue.length>=8){status.textContent='Cola llena. Confirma o cancela las acciones pendientes.';return false;}queue.push({tool,args});pump();return true;}
function locationOnImage(clientX,clientY){if(!frame||!frame.width||!frame.height)return null;const rect=view.getBoundingClientRect(),scale=Math.min(rect.width/frame.width,rect.height/frame.height),w=frame.width*scale,h=frame.height*scale,left=rect.left+(rect.width-w)/2,top=rect.top+(rect.height-h)/2;const x=(clientX-left)/w,y=(clientY-top)/h;if(x<0||x>1||y<0||y>1)return null;return{x,y};}
function touch(clientX,clientY,action){const p=locationOnImage(clientX,clientY);if(!p||!target.value||Date.now()-imageTime>3000){status.textContent='Indica una ventana y espera una imagen actual.';return;}send('remote_touch',{window:target.value,x:p.x,y:p.y,frame_id:frame.id,action});}
view.onpointerdown=e=>{points.set(e.pointerId,[e.clientX,e.clientY]);view.setPointerCapture(e.pointerId);if(points.size===1)gesture={scroll:false,scrollY:e.clientY};if(points.size>=2&&gesture)gesture.scroll=true;};
view.onpointermove=e=>{if(!points.has(e.pointerId))return;points.set(e.pointerId,[e.clientX,e.clientY]);if(gesture&&gesture.scroll&&points.size>=2){const values=[...points.values()],y=(values[0][1]+values[1][1])/2;if(Math.abs(y-gesture.scrollY)>20&&Date.now()-lastScroll>600){touch(values[0][0],values[0][1],y<gesture.scrollY?'down':'up');lastScroll=Date.now();gesture.scrollY=y;}}};
view.onpointerup=e=>{if(gesture&&!gesture.scroll)touch(e.clientX,e.clientY,'click');points.delete(e.pointerId);if(!points.size)gesture=null;};view.onpointercancel=e=>{points.delete(e.pointerId);gesture=null;};
const keyboardStatus=document.getElementById('keyboardStatus');
let mirrored='',composing=false,targetOwner='';
function keyboardNotice(message){keyboardStatus.textContent=message;if(keyboardChannel&&keyboardChannel.closed){typing.disabled=true;mirrored='';typing.value='';}}
function showKeyboard(){document.getElementById('keyboardBox').hidden=false;typing.disabled=!keyboardChannel||keyboardChannel.closed;if(!typing.disabled){typing.focus({preventScroll:true});try{if(navigator.virtualKeyboard)navigator.virtualKeyboard.show();}catch(_){}}}
document.getElementById('keyboard').onclick=showKeyboard;
function focusChanged(info){const changed=!focusInfo||focusInfo.field!==info.field||focusInfo.editable!==info.editable;focusInfo=info;if(info.window===target.value)targetOwner=info.owner||'';if(changed){mirrored='';typing.value='';}if(changed&&info.editable&&(info.window===target.value||(targetOwner&&info.owner===targetOwner))){showKeyboard();keyboardNotice('Campo de texto detectado. Si el teclado no se abre, pulsa Teclado (restricción del navegador).');}}
view.addEventListener('pointerup',()=>{if(focusInfo&&focusInfo.editable&&(focusInfo.window===target.value||(targetOwner&&focusInfo.owner===targetOwner)))showKeyboard();});
function transmit(events){try{if(!keyboardChannel)throw Error('Espera a que conecte el teclado.');keyboardChannel.push(events);return true;}catch(e){keyboardNotice(e.message);return false;}}
function modifiers(){return ['ctrl','alt','shift'].filter(k=>document.getElementById(k).checked);}
function clearMirror(){mirrored='';typing.value='';}
function special(key,mods=modifiers()){if(transmit([VictorKeys.keyEvent(key,mods)]))clearMirror();}
function commit(){if(composing)return;try{const events=VictorKeys.editEvents(mirrored,typing.value);const mods=modifiers();if(mods.length&&events.length===1&&events[0].kind==='text'&&/^[a-z0-9]$/i.test(events[0].text)){special(events[0].text,mods);return;}if(transmit(events)){mirrored=Array.from(typing.value).slice(-128).join('');typing.value=mirrored;typing.setSelectionRange(typing.value.length,typing.value.length);}else clearMirror();}catch(e){keyboardNotice(e.message);clearMirror();}}
typing.oncompositionstart=()=>composing=true;
typing.oncompositionend=()=>{composing=false;commit();};
typing.oninput=()=>commit();
typing.onkeydown=e=>{if(composing||e.isComposing)return;const mods=[...new Set(modifiers().concat(e.ctrlKey?['ctrl']:[],e.altKey?['alt']:[],e.shiftKey?['shift']:[],e.metaKey?['win']:[]))];if(['Enter','Escape','Backspace','Delete','Tab','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End','PageUp','PageDown','F4'].includes(e.key)||((e.ctrlKey||e.altKey||e.metaKey)&&/^[a-z0-9]$/i.test(e.key))){e.preventDefault();special(e.key,mods);}};
typing.onbeforeinput=e=>{if(composing||e.isComposing)return;if(e.inputType==='deleteContentBackward'&&!typing.value){e.preventDefault();special('backspace');}else if(e.inputType==='insertLineBreak'||e.inputType==='insertParagraph'){e.preventDefault();special('enter');}};
document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{special(b.dataset.key);showKeyboard();});
target.addEventListener('change',()=>{targetOwner='';clearMirror();});
document.getElementById('screen').onclick=()=>send('remote_screen_stream',{});
document.getElementById('stop').onclick=()=>{running=false;queue=[];buffer='';if(keyboardChannel)keyboardChannel.fail('Teclado detenido');if(ws)ws.close();if(video)video.close();status.textContent='Sesión detenida. Genera un nuevo QR para reconectar.';};
setInterval(()=>{if(!running)return;if(ws&&ws.readyState===1){if(Date.now()-lastControl>15000){ws.close();return;}ws.send(JSON.stringify({type:'ping'}));}if(video&&video.readyState===1&&imageTime&&Date.now()-imageTime>3000){view.style.opacity='.45';status.textContent=pending?'Esperando confirmación en el PC.':'Imagen sin actualizar. Renueva la pantalla.'}},1000);
(async()=>{try{[ws,{session}]=await connect('/control',{code});status.textContent='Conectado. Indica la ventana destino.';ws.onmessage=e=>{const m=JSON.parse(e.data);lastControl=Date.now();if(m.type==='pong')return;status.textContent=m.message||m.error||'Listo';if(m.done){pending=false;setTimeout(pump,500)}};ws.onclose=()=>{pending=false;queue=[];running=false;if(keyboardChannel)keyboardChannel.fail('Sesión cerrada. Vuelve a emparejar.');if(video)video.close();status.textContent='Sesión cerrada. Revisa Wi-Fi/HTTPS y genera otro QR en el PC; si el certificado caducó, reinicia el remoto.'};connect('/keyboard',{session}).then(([keySocket])=>{keyboardChannel=new VictorKeys.Channel(keySocket,()=>target.value,keyboardNotice,focusChanged);keyboardNotice('Teclado conectado · QR autorizado');}).catch(e=>keyboardNotice(e.message));[video]=await connect('/screen',{session});video.onclose=()=>{status.textContent='Conexión de pantalla cerrada. Genera otro QR para reconectar.';view.style.opacity='.45';};video.onerror=()=>{status.textContent='Falló la conexión de pantalla. Revisa Wi-Fi y certificado HTTPS.';};video.binaryType='blob';video.onmessage=e=>{if(e.data instanceof Blob){if(imageURL)URL.revokeObjectURL(imageURL);imageURL=URL.createObjectURL(e.data);frame=metadata;view.src=imageURL;imageTime=Date.now();view.style.opacity='1'}else{const m=JSON.parse(e.data);if(m.frame)metadata=m.frame;else status.textContent=m.error||'Pantalla detenida'}};send('remote_screen_stream',{});}catch(e){status.textContent=e.message}})();
</script></html>'''

PAGE = PAGE.replace("<script>", "<script>\n" + KEYBOARD_JS, 1)
